{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name='SELECT ts.trip' GROUP BY 1,2 UNION ALL SELECT 'no', span_name, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-travel-service' AND span_name='SELECT ts.trip' GROUP BY 1,2",
          "claim": "Travel-service's 'SELECT ts.trip' DB span p95 rises from about 1 ms to about 1589 ms, with no error status."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Internal' AND span_name LIKE 'TripRepository.%' GROUP BY 1",
          "claim": "Travel's internal TripRepository methods (findAll, findByTripId) take seconds in the abnormal window, while the work inside them is a single DB call."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, service_name, attr_span_kind k, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Sibling ts-travel2-service's server spans stay near normal (p95 in tens of ms), so the slowdown is specific to travel-service's DB path."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) caller_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL",
          "claim": "Route-plan's client calls into travel take about 4.4 s median, matching travel's server time almost exactly."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) caller_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL",
          "claim": "Travel-plan's client calls into route-plan take about 10.5 s median, mirroring route-plan's server time."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) caller_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-food-service' AND s.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL",
          "claim": "Food-service's calls to travel take about 1.6 s median, matching travel's server time."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE 'GET /api/v1/foodservice/foods/%' GROUP BY 1,2",
          "claim": "User-facing dashboard food-query requests reach multi-second p95 latency, inheriting food-service's wait on travel."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2 UNION ALL SELECT 'no', span_name, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Travel-plan server endpoints used by the dashboard rise from about 1.5 s to about 20-25 s p95."
        }
      ]
    }
  ]
}
